  const [showSettings, setShowSettings] = useState(false);

  const [view, setView] = useState("year"); // 'year' | 'month' | 'day'
  const [selYear, setSelYear] = useState(LAST_DATA_YEAR);
  const [selMonth, setSelMonth] = useState(LAST_DATA_MONTH);
  const [selDay, setSelDay] = useState(LAST_DATA_DAY);

  const goDay = (y, m, d) => { setSelYear(y); setSelMonth(m); setSelDay(d); setView("day"); };
  const goMonth = (y, m) => { setSelYear(y); setSelMonth(m); setView("month"); };
  const goYear = (y) => { setSelYear(y); setView("year"); };

  // ---------- full-year dataset ----------
  const yearDays = useMemo(() => {
    const out = [];
    for (let m = 0; m < 12; m++) {
      const dim = daysInMonth(selYear, m);
      for (let d = 1; d <= dim; d++) out.push(makeDayData(selYear, m, d, capacity, annualYield, annualUserKwh));
    }
    return out;
  }, [selYear, capacity, annualYield, annualUserKwh]);

  const monthlyAgg = useMemo(() => {
    return Array.from({ length: 12 }, (_, m) => {
      const days = yearDays.filter((d) => d.month === m);
      const agg = aggregate(days);
      return { monthIndex: m, label: MONTHS_TH[m], hasData: agg.count > 0, ...agg };
    });
  }, [yearDays]);

  const monthDays = useMemo(() => yearDays.filter((d) => d.month === selMonth), [yearDays, selMonth]);
