function PanelTitle({ title, sub }) {
  return (
    <div className="mb-3">
      <h3 className="display text-sm sm:text-base font-semibold" style={{ color: "var(--text)" }}>{title}</h3>
      {sub && <div className="text-[11px] mt-0.5" style={{ color: "var(--text-muted)" }}>{sub}</div>}
    </div>
  );
}
function MiniStat({ label, value, color }) {
  return (
    <div className="rounded-xl p-3" style={{ background: "var(--panel-2)", border: "1px solid var(--border)" }}>
      <div className="text-[10px]" style={{ color: "var(--text-muted)" }}>{label}</div>
      <div className="mono text-lg font-semibold" style={{ color }}>{value}</div>
    </div>
  );
}
function SpecItem({ label, value }) {
  return (
    <div>
      <div style={{ color: "var(--text-muted)" }}>{label}</div>
      <div className="mono" style={{ color: "var(--text)" }}>{value}</div>
    </div>
  );
}
function ThemedTooltip({ active, payload, label, unit }) {
  if (!active || !payload || !payload.length) return null;
  return (
    <div className="panel px-3 py-2 text-xs" style={{ boxShadow: "0 8px 24px rgba(0,0,0,0.4)" }}>
      <div className="mono mb-1" style={{ color: "var(--text-muted)" }}>{label}</div>
      {payload.map((p, i) => p.value != null && (
        <div key={i} className="flex items-center gap-2">
          <span className="w-2 h-2 rounded-full" style={{ background: p.color || p.stroke || p.fill }} />
          <span style={{ color: "var(--text-muted)" }}>{p.name}:</span>
          <span className="mono" style={{ color: "var(--text)" }}>{p.value}{unit}</span>
        </div>
      ))}
    </div>
  );
}

function PRGauge({ value, target }) {
  const size = 220, cx = size / 2, cy = size / 2 + 6, r = 82;
  const toXY = (pct, radius) => { const a = Math.PI + (pct / 100) * Math.PI; return { x: cx + radius * Math.cos(a), y: cy + radius * Math.sin(a) }; };
  const start = toXY(0, r), end = toXY(100, r);
  const needleEnd = toXY(Math.min(100, Math.max(0, value)), r - 14);
  const targetPt1 = toXY(target, r - 20), targetPt2 = toXY(target, r + 6);
  const color = value >= target ? "var(--accent-green)" : value >= target - 10 ? "var(--accent-amber)" : "var(--accent-red)";
  const valueArc = toXY(Math.min(100, Math.max(0, value)), r);
  const arcPath = (from, to, radius) => `M ${from.x} ${from.y} A ${radius} ${radius} 0 0 1 ${to.x} ${to.y}`;
  return (
    <div className="flex flex-col items-center justify-center py-2">
      <svg width={size} height={size / 1.7} viewBox={`0 0 ${size} ${size / 1.6}`}>
        <path d={arcPath(start, end, r)} stroke="var(--border)" strokeWidth="10" fill="none" strokeLinecap="round" />
        <path d={arcPath(start, valueArc, r)} stroke={color} strokeWidth="10" fill="none" strokeLinecap="round" />
        <line x1={targetPt1.x} y1={targetPt1.y} x2={targetPt2.x} y2={targetPt2.y} stroke="var(--accent-violet)" strokeWidth="2.5" />
        <line x1={cx} y1={cy} x2={needleEnd.x} y2={needleEnd.y} stroke="var(--text)" strokeWidth="2.5" strokeLinecap="round" />
        <circle cx={cx} cy={cy} r="5" fill="var(--text)" />
        <text x={cx} y={cy - 30} textAnchor="middle" className="mono" fontSize="26" fontWeight="700" fill={color}>{value.toFixed(1)}%</text>
        <text x={start.x - 4} y={start.y + 14} textAnchor="middle" fontSize="10" fill="var(--text-muted)">0</text>
        <text x={end.x + 4} y={end.y + 14} textAnchor="middle" fontSize="10" fill="var(--text-muted)">100</text>
      </svg>
    </div>
  );
}
